insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_38_v1'
from (values
('127.227.d.1.A',3,'A practicum student tells the camera operator which shot comes next, using a clear voice and a pointed hand signal. This is:','["verbal and non-verbal communication", "an edit", "silent guessing", "a written contract"]'::jsonb,0,'Words and gestures together make instructions clear.','original'),
('127.227.d.1.A',4,'On a noisy set, which approach keeps instructions clear?','["Send a long email later", "Pair short spoken cues with agreed hand signals", "Whisper and hope", "Wait for others to ask"]'::jsonb,1,'Combining voice and signals prevents misunderstanding.','original'),
('127.227.d.1.B',3,'A student reads ratings from three test screenings and tells the director which scene viewers liked most. She is:','["ignoring results", "erasing notes", "interpreting and communicating data", "guessing"]'::jsonb,2,'Making sense of data and sharing it is a core skill.','original'),
('127.227.d.1.B',4,'Which statement reports screening data most clearly?','["People mostly liked it, probably.", "Some viewers said things.", "The scene seemed good.", "Seventy percent of viewers rated the opening scene four or five stars."]'::jsonb,3,'Specific figures give clear information.','original'),
('127.227.d.1.C',3,'At the end of the semester, a student plays her documentary for a panel and explains her production choices. This is a:','["formal presentation", "password reset", "tool check", "private rehearsal"]'::jsonb,0,'A planned showing with explanation is formal.','original'),
('127.227.d.1.C',4,'What helps a presentation of a finished video reach an audience effectively?','["Hiding the end", "A brief introduction, a clear structure, and time for questions", "Reading a script word for word at high speed", "Skipping the introduction"]'::jsonb,1,'Structure and interaction keep audiences engaged.','original'),
('127.227.d.1.D',3,'A student calls a customer to explain a delay and offers a new delivery date. This builds:','["tension", "mistrust", "customer trust through public relations", "confusion"]'::jsonb,2,'Honest, prompt updates protect relationships.','original'),
('127.227.d.1.D',4,'Which action protects a production company''s reputation with its community?','["Deleting all comments", "Blaming viewers", "Ignoring feedback", "Responding politely to questions and complaints"]'::jsonb,3,'Courteous replies show professionalism.','original'),
('127.227.d.2.A',3,'A student fixes a flickering video clip by checking the cable, the file, and the player one at a time. This shows:','["independent critical thinking", "avoidance", "carelessness", "panic"]'::jsonb,0,'Testing one factor at a time is critical thinking.','original'),
('127.227.d.2.A',4,'A group of students must pick the best of three edits. Which approach shows critical thinking?','["Choose the longest", "Compare each edit to the project goals and discuss the evidence", "Flip a coin", "Choose the first"]'::jsonb,1,'Evaluating against goals supports good decisions.','original'),
('127.227.d.2.B',3,'A student uses what she learned in a lighting unit to light a new interview set. This shows:','["avoiding the task", "copying exactly", "transfer of knowledge", "forgetting"]'::jsonb,2,'Knowledge from one unit is adapted to a new setting.','original'),
('127.227.d.2.B',4,'Which example best shows creating a new product by adapting prior knowledge?','["Starting without any plan", "Skipping the project", "Repeating the same project", "Using editing rhythm lessons from a music video to cut a safety training film"]'::jsonb,3,'Adapting techniques to new content shows transfer.','original'),
('127.227.d.3.A',3,'Before a shoot, the crew tapes down cables and checks the light stands. They are following:','["workplace safety rules", "naming rules", "menu rules", "fashion rules"]'::jsonb,0,'Safe setup prevents injuries.','original'),
('127.227.d.3.A',4,'Why must everyone know where the fire exits and first-aid kit are?','["To reduce power use", "So help is fast in an emergency", "To decorate", "To impress clients"]'::jsonb,1,'Knowing the locations saves time in an emergency.','original'),
('127.227.d.3.B',3,'A student sees a coiled cable across a doorway. What should she do?','["Leave it for another shift", "Step over it", "Move it or mark it to prevent tripping", "Ignore it"]'::jsonb,2,'Resolve hazards right away.','original'),
('127.227.d.3.B',4,'A hot light is placed next to a curtain. Which action resolves the safety concern?','["Cover the light with cloth", "Add another light", "Turn the lights up", "Move the light away and keep flammable items clear"]'::jsonb,3,'Heat near fabric can cause a fire.','original'),
('127.227.d.4.A',3,'A practicum student arrives early, finishes her tasks, and offers to help others. She shows a strong:','["work ethic", "excuse", "shortcut", "delay"]'::jsonb,0,'Reliability and effort are work ethic.','original'),
('127.227.d.4.A',4,'Which behavior shows a productive work ethic during a busy shoot?','["Waiting for orders each time", "Completing assigned duties without needing reminders", "Working slowly", "Taking long breaks"]'::jsonb,1,'Self-direction is valued on crews.','original'),
('127.227.d.4.B',3,'A student''s documentary uses an interview clip from a classmate. Ethical practice means she:','["changes the voice", "keeps quiet", "gives the classmate credit in the credits", "hides the name"]'::jsonb,2,'Proper credit is ethical conduct.','original'),
('127.227.d.4.B',4,'Which action best shows integrity in crediting a team project?','["Listing only yourself", "Crediting only friends", "Skipping credits", "Listing every contributor''s role in the credits"]'::jsonb,3,'Accurate credits respect everyone''s work.','original'),
('127.227.d.4.C',3,'A student wants to blend a clip from a movie into her project. To respect intellectual property, she should:','["get permission or use licensed material", "claim it as hers", "use it without asking", "remove the logo"]'::jsonb,0,'Using others'' work requires permission.','original'),
('127.227.d.4.C',4,'Reworking a copyrighted photo with filters before using it in a video:','["makes it free to use", "does not remove the owner''s rights", "creates a new copyright for you", "cancels the copyright"]'::jsonb,1,'Changes do not erase ownership.','original'),
('127.227.d.4.D',3,'Which choice shows safe, legal, and responsible use of technology in a studio?','["Using pirated plug-ins", "Sharing passwords", "Using licensed editing software", "Opening unknown links"]'::jsonb,2,'Licensed tools are legal and safe.','original'),
('127.227.d.4.D',4,'A student is asked to download a free copy of a paid editing program. The responsible choice is to:','["do it quickly", "install it on every computer", "share the file", "decline and use the licensed version"]'::jsonb,3,'Illegal copies violate copyright law.','original'),
('127.227.d.4.E',3,'Choosing to report a mistake in a client''s invoice instead of ignoring it shows:','["integrity", "carelessness", "greed", "laziness"]'::jsonb,0,'Integrity means choosing the ethical course.','original'),
('127.227.d.4.E',4,'A student realizes she accidentally recorded over a classmate''s clip. The ethical choice is to:','["hide it", "tell the classmate and help recover or recreate it", "say nothing", "blame someone else"]'::jsonb,1,'Honesty is part of integrity.','original'),
('127.227.d.4.F',3,'Following all workplace rules, laws, and regulations should be done:','["only sometimes", "never", "every day, consistently", "only when watched"]'::jsonb,2,'Compliance is an everyday habit.','original'),
('127.227.d.4.F',4,'Which example shows following regulations in a production job?','["Skipping safety checks", "Filming anyone without asking", "Using any music", "Having signed releases from people who appear on camera"]'::jsonb,3,'Releases protect the production legally.','original'),
('127.227.d.5.A',3,'A practicum student works with a professional crew and logs what she learned each week. She is:','["documenting learning activities", "avoiding feedback", "hiding work", "skipping tasks"]'::jsonb,0,'Documentation shows progress.','original'),
('127.227.d.5.A',4,'Why does a mentor review a practicum student''s work log?','["To punish", "To evaluate learning and guide improvement", "To waste time", "To avoid mentoring"]'::jsonb,1,'Review supports growth.','original'),
('127.227.d.5.B',3,'A student learns a color-grading workflow used by her mentoring studio. This is developing:','["basic hobbies", "beginner chores only", "advanced technical knowledge", "unrelated skills"]'::jsonb,2,'Advanced skills prepare students for a career.','original'),
('127.227.d.5.B',4,'Which practicum activity best builds advanced technical skill in audio production?','["Reading a menu", "Moving chairs", "Watching unrelated videos", "Mixing dialogue, music, and effects for a real project"]'::jsonb,3,'Real mixing work builds professional skill.','original'),
('127.227.d.5.C',3,'A client-based production is a project made for:','["a customer who has needs and approvals", "a game score", "no one", "only the student"]'::jsonb,0,'Client work requires meeting someone else''s requirements.','original'),
('127.227.d.5.C',4,'What distinguishes client work from a personal project?','["No budget", "The client''s goals, approvals, and deadlines guide decisions", "No audience", "No deadline"]'::jsonb,1,'Clients set requirements.','original'),
('127.227.d.5.D',3,'Casting, locating equipment, and scheduling the shoot are part of:','["archiving", "distribution", "pre-production", "post-production"]'::jsonb,2,'Planning happens before filming.','original'),
('127.227.d.5.D',4,'Which task belongs to pre-production?','["Color grading", "Exporting the final file", "Uploading to a site", "Scouting a location and booking the crew"]'::jsonb,3,'Scouting and booking come before the shoot.','original'),
('127.227.d.5.E',3,'Operating the camera and recording sound on the shoot day is part of:','["production", "archiving", "pre-production", "marketing"]'::jsonb,0,'Production is the filming stage.','original'),
('127.227.d.5.E',4,'Which is a production-stage task?','["Writing the proposal", "Monitoring audio levels while the scene is recorded", "Delivering the file", "Designing the poster"]'::jsonb,1,'Monitoring audio happens during recording.','original'),
('127.227.d.5.F',3,'Editing footage, mixing sound, and exporting for the client is part of:','["casting", "pre-production", "post-production", "scouting"]'::jsonb,2,'Finishing work occurs after filming.','original'),
('127.227.d.5.F',4,'The client''s player cannot open the file. The student re-exports it in a compatible format. This is a:','["set design", "script rewrite", "casting change", "post-production adjustment"]'::jsonb,3,'Compatibility fixes are made when finishing.','original'),
('127.227.d.5.G',3,'A student finishes tasks that used to take her twice as long. This shows:','["growth of technical skill", "no change", "lost ability", "avoidance"]'::jsonb,0,'Increasing speed shows skill growth.','original'),
('127.227.d.5.G',4,'Which evidence best shows skill growth over a practicum?','["Ignoring earlier work", "Comparing early projects with recent ones", "Skipping evaluations", "Deleting old files"]'::jsonb,1,'Comparison reveals progress.','original'),
('127.227.d.5.H',3,'A student lists the techniques she handles well and those she still needs to practice. She is evaluating her:','["hobbies", "salary", "strengths and weaknesses", "address"]'::jsonb,2,'Self-assessment directs practice.','original'),
('127.227.d.5.H',4,'Why identify weaknesses in technical skills?','["To skip the lab", "To feel discouraged", "To avoid feedback", "To plan targeted practice"]'::jsonb,3,'Knowing a weakness helps you improve it.','original'),
('127.227.d.5.I',3,'Saving the best finished videos and mentor comments to show employers is collecting:','["representative work samples", "unfinished sketches only", "junk files", "empty folders"]'::jsonb,0,'Samples show real skill.','original'),
('127.227.d.5.I',4,'Which sample best represents a student''s editing skills?','["A blank timeline", "A polished, finished project with clean cuts and mixed audio", "A grocery list", "A corrupted file"]'::jsonb,1,'Complete, polished work shows ability.','original'),
('127.228.d.4',3,'An employee in a print shop uses design software, email, and a job-tracking program to run orders. These are:','["paper stocks", "hand tools", "advanced technology applications", "press plates"]'::jsonb,2,'Software supports modern print production.','original'),
('127.228.d.4',4,'A print shop uses a web-to-print portal where customers upload their files. This technology mainly:','["replaces the press", "lowers paper quality", "removes customer files", "speeds up order intake"]'::jsonb,3,'Online portals streamline orders.','original'),
('127.228.d.9',3,'Learning to set up a folder, cutter, and press quickly and correctly builds technical skills for:','["efficiency", "waste", "rework", "delay"]'::jsonb,0,'Skilled setup reduces time and errors.','original'),
('127.228.d.9',4,'Which habit improves efficiency in a print shop?','["Printing before proofs", "Grouping similar jobs to reduce changeovers", "Switching jobs constantly", "Skipping setup checks"]'::jsonb,1,'Fewer changeovers save time.','original'),
('127.228.d.1.A',3,'A print technician carefully proofreads a customer''s brochure for spelling errors before printing. She is applying:','["woodworking", "music theory", "English language arts knowledge", "gym skills"]'::jsonb,2,'Language skills prevent costly errors.','original'),
('127.228.d.1.A',4,'Which task uses English language arts skills in a print shop?','["Sharpening a blade", "Calibrating a lens", "Mixing ink", "Writing a clear job ticket with correct instructions"]'::jsonb,3,'Clear writing prevents production mistakes.','original'),
('127.228.d.1.B',3,'A customer orders 500 flyers at $0.12 each. What is the total cost?','["$60", "$50", "$600", "$6"]'::jsonb,0,'500 x 0.12 = 60.','original'),
('127.228.d.1.B',4,'A job needs 1,200 sheets, and 5% extra are added for waste. How many sheets should be pulled?','["1,205", "1,260", "1,250", "1,320"]'::jsonb,1,'1,200 x 1.05 = 1,260.','original'),
('127.228.d.2.A',3,'A print shop employee uses simple language to explain paper options to a first-time customer. She is adapting language for the:','["press", "ink", "audience", "cutter"]'::jsonb,2,'Plain words help non-experts.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_38_v1'
from (values
('127.228.d.2.A',4,'A shop writes a formal quote to a company and a quick text to a regular customer. They are changing:','["ink color", "paper weight", "press speed", "style for the situation"]'::jsonb,3,'Style depends on audience and purpose.','original'),
('127.228.d.2.B',3,'Writing job details in order from customer name to due date is:','["organizing information", "guessing", "erasing information", "hiding information"]'::jsonb,0,'Organized details prevent errors.','original'),
('127.228.d.2.B',4,'Which job ticket is best organized?','["A blank sheet", "One with customer, quantity, paper, finishing, and due date in clear fields", "A list in random order", "A single paragraph of notes"]'::jsonb,1,'Clear fields speed production.','original'),
('127.228.d.2.C',3,'A technician records ink density readings on a sheet and reports them to a supervisor. She is:','["erasing numbers", "ignoring results", "communicating observations and data", "guessing"]'::jsonb,2,'Reporting readings helps quality control.','original'),
('127.228.d.2.C',4,'Which report of a quality problem is most useful?','["Something was off.", "It''s not right.", "Colors looked weird.", "The magenta ink density dropped to 1.1 after 2,000 sheets."]'::jsonb,3,'Specific observations help fix problems.','original'),
('127.228.d.2.D',3,'A student explains each step of the printing process to visiting parents. This is:','["presenting information", "avoiding people", "hiding steps", "ignoring questions"]'::jsonb,0,'Presenting shares knowledge.','original'),
('127.228.d.2.D',4,'Which is an informal way to present a printing method?','["Delivering a keynote", "Showing a coworker how to load the folder at the machine", "Writing a legal brief", "Filing taxes"]'::jsonb,1,'Casual demonstration is informal.','original'),
('127.228.d.2.E',3,'A customer explains how she wants her wedding invitations folded. The employee writes notes and repeats the details back. This is:','["interrupting", "daydreaming", "active listening", "ignoring"]'::jsonb,2,'Repeating details confirms understanding.','original'),
('127.228.d.2.E',4,'What should a press operator do if a job instruction is unclear?','["Guess", "Wait until the job is wrong", "Start anyway", "Ask for clarification before starting"]'::jsonb,3,'Clarify before production.','original'),
('127.228.d.2.F',3,'A print shop serves customers from many cultures. A good employee will:','["listen with respect to each customer", "ignore accents", "assume needs", "rush people"]'::jsonb,0,'Respect improves service.','original'),
('127.228.d.2.F',4,'A customer who speaks little English wants business cards. A respectful response is to:','["finish their sentences", "speak slowly, use visual samples, and confirm details", "walk away", "use difficult words"]'::jsonb,1,'Visual aids bridge language gaps.','original'),
('127.228.d.2.G',3,'Calling a customer promptly to say their order is ready shows:','["press skills", "poor planning", "public relations skills", "folding skills"]'::jsonb,2,'Courtesy builds loyalty.','original'),
('127.228.d.2.G',4,'A shop prints an error and quickly reprints it at no charge. This builds:','["delay", "resentment", "tension", "customer goodwill"]'::jsonb,3,'Fixing mistakes protects relationships.','original'),
('127.228.d.3.A',3,'A shift team splits a large print run into tasks and works together to finish it. This uses:','["critical thinking in a group", "guessing", "isolation", "luck"]'::jsonb,0,'Groups plan and decide together.','original'),
('127.228.d.3.A',4,'Which action shows critical thinking when a press leaves streaks?','["Adding water at random", "Checking the plates, blanket, and ink in turn", "Ignoring streaks", "Restarting repeatedly"]'::jsonb,1,'Testing causes one by one finds the source.','original'),
('127.228.d.3.B',3,'Two operators disagree about the best paper for a job. The best step is to:','["skip the job", "let one yell louder", "compare the choices against the customer''s needs", "flip a coin"]'::jsonb,2,'Customer needs guide decisions.','original'),
('127.228.d.3.B',4,'Which phrase helps a team solve a production problem?','["You messed it up.", "That''s not my job.", "Not my problem.", "What options do we have to meet the deadline?"]'::jsonb,3,'Solution-focused talk helps.','original'),
('127.228.d.5.A',3,'Wearing safety glasses and keeping long hair tied back near a press is following:','["workplace safety rules", "style rules", "price rules", "spelling rules"]'::jsonb,0,'PPE and tied-back hair prevent accidents.','original'),
('127.228.d.5.A',4,'Before clearing a jam in a cutter, an operator should first:','["reach in quickly", "shut off and lock out the power", "keep it running", "wear loose sleeves"]'::jsonb,1,'Lockout prevents injury.','original'),
('127.228.d.5.B',3,'If there is a chemical spill in the shop, employees should:','["mop with paper towels", "ignore it", "follow the posted emergency procedure", "leave it overnight"]'::jsonb,2,'Procedures limit harm.','original'),
('127.228.d.5.B',4,'Where can workers find how to handle a hazardous ink safely?','["On the poster", "On the paper box", "On the invoice", "In the safety data sheet"]'::jsonb,3,'SDS lists hazards and first-aid steps.','original'),
('127.228.d.6.A',3,'A shop lead sets daily goals, assigns tasks, and checks progress. She is showing:','["leadership skills", "carelessness", "laziness", "avoidance"]'::jsonb,0,'Leaders guide the team toward goals.','original'),
('127.228.d.6.A',4,'When a rush order arrives, a good leader will:','["blame the customer", "rearrange tasks and inform the team", "ignore the order", "stop all work"]'::jsonb,1,'Leaders adapt plans.','original'),
('127.228.d.6.B',3,'Two operators argue over who gets the folder first. A teammate suggests a schedule that fits both jobs. This is:','["avoidance", "blame", "conflict management", "competition"]'::jsonb,2,'Compromise solves conflict.','original'),
('127.228.d.6.B',4,'Which statement supports teamwork?','["I''m not sharing.", "Figure it out yourself.", "It''s my turn only.", "Let''s schedule both jobs so each is on time."]'::jsonb,3,'Cooperative language keeps the team working.','original'),
('127.228.d.6.C',3,'Thanking a coworker for helping with a rush job helps build:','["good working relationships", "tension", "distance", "resentment"]'::jsonb,0,'Appreciation builds trust.','original'),
('127.228.d.6.C',4,'Which is constructive feedback on a trimmed stack?','["You can''t cut.", "The cuts are clean; check the guide for the last few sheets.", "That''s bad.", "Never mind."]'::jsonb,1,'Specific, kind feedback helps.','original'),
('127.228.d.6.D',3,'A supervisor lists topics and time limits before a staff meeting. She is:','["wasting time", "skipping the meeting", "preparing goals for the meeting", "avoiding work"]'::jsonb,2,'An agenda focuses the meeting.','original'),
('127.228.d.6.D',4,'Which goal fits a weekly production meeting?','["Talk about movies", "Tell jokes", "Argue about parking", "Decide the order of jobs for next week"]'::jsonb,3,'Meeting goals should be work-related.','original'),
('127.228.d.6.E',3,'During a shop meeting, employees should:','["stay on topic and share updates", "talk over others", "leave early", "use phones"]'::jsonb,0,'Focus accomplishes tasks.','original'),
('127.228.d.6.E',4,'After a meeting, which step keeps tasks moving?','["Deleting the agenda", "Sending notes that list who will do what", "Saying nothing", "Waiting until next week"]'::jsonb,1,'Written follow-up creates accountability.','original'),
('127.228.d.6.F',3,'A veteran press operator shows a new hire how to set up a folder. This is:','["competing", "avoiding", "mentoring", "copying"]'::jsonb,2,'Mentors teach and inspire.','original'),
('127.228.d.6.F',4,'A good mentor in a print shop:','["corrects harshly", "hides tricks", "avoids questions", "explains the why behind each step patiently"]'::jsonb,3,'Patient explanation builds skill.','original'),
('127.228.d.7.A',3,'A print shop employee keeps customers'' artwork and personal data private. This shows:','["ethical conduct", "gossip", "carelessness", "competition"]'::jsonb,0,'Confidentiality is ethical conduct.','original'),
('127.228.d.7.A',4,'A customer''s unreleased product design is on a proof. The employee should:','["post it online", "keep it confidential", "show other customers", "take a photo for fun"]'::jsonb,1,'Client information is private.','original'),
('127.228.d.7.B',3,'Copying a whole book for sale without permission violates:','["safety rules", "ink rules", "copyright law", "paper rules"]'::jsonb,2,'Copyright protects authors.','original'),
('127.228.d.7.B',4,'A customer asks a shop to duplicate a published workbook for a class of 30. The shop should first:','["remove the title", "charge extra", "print immediately", "verify copyright permission or fair use"]'::jsonb,3,'Duplication may need permission.','original'),
('127.228.d.7.C',3,'Using a photograph in a flyer only after asking the photographer shows:','["respect for intellectual property", "carelessness", "disrespect", "theft"]'::jsonb,0,'Permission respects creators.','original'),
('127.228.d.7.C',4,'Which action respects intellectual property when designing a poster?','["Copying any image from a search", "Using licensed or original images", "Cropping out a watermark", "Claiming a stock photo is yours"]'::jsonb,1,'Licensed images are legal to use.','original'),
('127.228.d.7.D',3,'A school''s acceptable use policy forbids using lab printers for personal business. A student should:','["ask a friend", "hide it", "follow the policy", "print anyway"]'::jsonb,2,'Policies set the rules for equipment use.','original'),
('127.228.d.7.D',4,'Which action shows good etiquette with a shared printer?','["Leaving jams", "Printing hundreds of pages", "Changing others'' settings", "Collecting only your pages and refilling the paper"]'::jsonb,3,'Courtesy keeps shared equipment ready.','original'),
('127.228.d.7.E',4,'A designer finds a photo with a Creative Commons license that requires attribution. She must:','["credit the creator as the license requires", "change its name", "remove the license", "sell it as her own"]'::jsonb,0,'Attribution is a common requirement.','original'),
('127.228.d.8.A',3,'A print student keeps samples of her best brochures and a resume in a folder. She is maintaining a:','["menu", "portfolio", "tax form", "scrapbook of trash"]'::jsonb,1,'Portfolios show skills.','original'),
('127.228.d.8.A',4,'Why update a print portfolio regularly?','["To hide old samples", "To avoid interviews", "To show your newest and best work to employers", "To use more ink"]'::jsonb,2,'Current work shows growth.','original'),
('127.228.d.8.B',3,'A graduate compares two job offers by pay, benefits, and training. She is:','["picking at random", "avoiding work", "ignoring details", "evaluating employment opportunities"]'::jsonb,3,'Comparing options supports good choices.','original'),
('127.228.d.8.B',4,'Which factor matters most when comparing two print jobs for long-term growth?','["Training and advancement chances", "The color of the lobby", "The parking sign", "The brand of the vending machine"]'::jsonb,0,'Advancement shapes a career.','original'),
('127.228.d.8.C',3,'A trained printer opens her own copy and print shop. This is:','["unemployment", "entrepreneurship", "an internship", "retirement"]'::jsonb,1,'Entrepreneurs run their own businesses.','original'),
('127.228.d.8.C',4,'A challenge of owning a small print shop is:','["a guaranteed salary", "no expenses", "managing equipment costs and finding customers", "having no customers needed"]'::jsonb,2,'Owners handle sales and costs.','original'),
('127.228.d.10.A',3,'Offset lithography, digital printing, and screen printing are different:','["paper sizes", "ink brands", "cutters", "printing systems"]'::jsonb,3,'Each system has its uses.','original'),
('127.228.d.10.A',4,'For a short run of 50 full-color flyers, which system is usually most economical?','["Digital printing", "Letterpress", "Gravure", "Large offset setup"]'::jsonb,0,'Digital needs little setup for short runs.','original'),
('127.228.d.10.B',3,'Scheduling jobs, checking proofs, and tracking supplies is:','["only designing", "managing the printing process", "only folding", "only cutting"]'::jsonb,1,'Management coordinates all steps.','original'),
