('127.230.d.8.A',3,'A photographer gets signed model releases before publishing portraits. This shows:','["carelessness", "gossip", "ethical conduct", "greed"]'::jsonb,2,'Releases respect people''s rights.','original'),
('127.230.d.8.A',4,'A photographer shoots a stranger''s child at a park. The ethical choice is to:','["sell it", "ignore it", "post it online", "ask the parent for permission before publishing"]'::jsonb,3,'Consent matters, especially for minors.','original'),
('127.230.d.8.B',3,'A photographer owns the copyright to her photos unless:','["she transfers or licenses it in a contract", "she prints them", "a client uses them", "she posts them"]'::jsonb,0,'Contracts can transfer or license rights.','original'),
('127.230.d.8.B',4,'A client wants to print the photos on a billboard though the contract allowed web use only. The photographer should:','["ignore it", "discuss a new license and fee", "delete the photos", "allow it for free"]'::jsonb,1,'Use beyond the license needs a new agreement.','original'),
('127.230.d.8.C',3,'Editing and compositing someone else''s photograph into a collage requires:','["removing credit", "claiming authorship", "permission or a proper license", "no permission"]'::jsonb,2,'Altering a work does not remove rights.','original'),
('127.230.d.8.C',4,'Which respects intellectual property when assembling a composite?','["Removing watermarks", "Using any image online", "Claiming stock as yours", "Using only your own images or licensed ones"]'::jsonb,3,'Licensed or original images are safe.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
